

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .chat_completion_message_tool_call_chunk import ChatCompletionMessageToolCallChunk
from .chat_completion_stream_response_delta_function_call import ChatCompletionStreamResponseDeltaFunctionCall
from .chat_completion_stream_response_delta_role import ChatCompletionStreamResponseDeltaRole


class ChatCompletionStreamResponseDelta(UniversalBaseModel):
    """
    A chat completion delta generated by streamed model responses.
    """

    content: typing.Optional[str] = pydantic.Field(default=None)
    """
    The contents of the chunk message.
    """

    function_call: typing.Optional[ChatCompletionStreamResponseDeltaFunctionCall] = pydantic.Field(default=None)
    """
    Deprecated and replaced by `tool_calls`. The name and arguments of a function that should be called, as generated by the model.
    """

    tool_calls: typing.Optional[typing.List[ChatCompletionMessageToolCallChunk]] = None
    role: typing.Optional[ChatCompletionStreamResponseDeltaRole] = pydantic.Field(default=None)
    """
    The role of the author of this message.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
